function eventsFromItem(item, {
  sourceHostID,
  threadID,
  turn = {},
  liveParams = null,
  defaultMs = null,
  turnStartedAtMs = null,
  turnCompletedAtMs = null,
  turnOrder = null,
  itemOrder = null,
  renderState = "settled",
}) {
  const rawKind = item?.type || "unknown";
  const turnID = resolveIdentity("turnID", liveParams
    ? [
      { value: liveParams.turnId },
      { value: liveParams.turnID },
      { value: liveParams.turn?.id },
      { value: item?.turnId },
      { value: item?.turnID },
    ]
    : [
      { value: turn?.id },
      { value: turn?.turnId },
      { value: turn?.turnID },
    ]);
  const itemID = resolveIdentity("itemID", liveParams
    ? [
      { value: liveParams.itemId },
      { value: liveParams.itemID },
      { value: item?.id },
    ]
    : [
      { value: item?.id },
    ]);
  const activityAtMs = itemActivityMs(rawKind, {
    defaultMs,
    turnStartedAtMs,
    turnCompletedAtMs,
  }) ?? Date.now();

  if (!item || typeof item !== "object") {
    return [diagnosticEvent({
      sourceHostID,
      threadID,
      rawKind: "nonObjectItem",
      errorCode: "item_shape_invalid",
      activityAtMs,
    })];
  }

  if (turnID.error || itemID.error) {
    return [diagnosticEvent({
      sourceHostID,
      threadID,
      rawKind,
      turnID: turnID.value,
      itemID: itemID.value,
      errorCode: turnID.error || itemID.error,
      activityAtMs,
    })];
  }

  const sourceRef = sourceRefForItem({
    sourceHostID,
    threadID,
    turnID: turnID.value,
    itemID: itemID.value,
  });
  return rowSpecsForItem(item).map((spec) => makeProjectionRow({
    sourceHostID,
    threadID,
    projectionID: projectionIDForItem({
      sourceHostID,
      threadID,
      turnID: turnID.value,
      itemID: itemID.value,
      rowRole: spec.rowRole,
    }),
    sourceRef,
    itemType: rawKind,
    rowRole: spec.rowRole,
    visibility: spec.visibility,
    renderKind: spec.renderKind,
    title: spec.title,
    body: spec.body,
    eventTimeMs: activityAtMs,
    activityAtMs,
    turnID: turnID.value,
    itemID: itemID.value,
    turnOrder,
    itemOrder,
    rowOrder: spec.rowOrder,
    renderState,
  }));
}

