 52	function proofStatusForReport(report) {
 53	  if (PROOF_STATUS_VALUES.has(report?.status)) {
 54	    return report.status;
 55	  }
 56	  const ok = report?.summary?.ok;
 57	  if (typeof ok === "boolean") {
 58	    return ok ? "pass" : "fail";
 59	  }
 60	  return "blocked";
 61	}
 62	
 63	function finalizeProofReport(report) {
 64	  report.status = proofStatusForReport(report);
 65	  return report;
 66	}
