 68	function loadProofSchemas() {
 69	  const ajv = new Ajv({ allErrors: true, strict: true });
 70	  const validators = new Map();
 71	  for (const [kind, schemaFile] of KIND_TO_SCHEMA_FILE.entries()) {
 72	    const schemaPath = path.join(PROOF_SCHEMA_DIR, schemaFile);
 73	    const schema = JSON.parse(fs.readFileSync(schemaPath, "utf8"));
 74	    validators.set(kind, ajv.compile(schema));
 75	  }
 76	  return validators;
 77	}
