 79	function collectStrings(value, strings = []) {
 80	  if (typeof value === "string") {
 81	    strings.push(value);
 82	    return strings;
 83	  }
 84	  if (Array.isArray(value)) {
 85	    for (const item of value) {
 86	      collectStrings(item, strings);
 87	    }
 88	    return strings;
 89	  }
 90	  if (value && typeof value === "object") {
 91	    for (const item of Object.values(value)) {
 92	      collectStrings(item, strings);
 93	    }
 94	  }
 95	  return strings;
 96	}
 97	
 98	function collectForbiddenKeys(value, path = "$", hits = []) {
 99	  if (Array.isArray(value)) {
100	    value.forEach((item, index) => collectForbiddenKeys(item, `${path}[${index}]`, hits));
101	    return hits;
102	  }
103	  if (!value || typeof value !== "object") {
104	    return hits;
105	  }
106	  for (const [key, child] of Object.entries(value)) {
107	    const childPath = `${path}.${key}`;
108	    if (FORBIDDEN_PROOF_KEYS.has(key)) {
109	      hits.push(childPath);
110	    }
111	    collectForbiddenKeys(child, childPath, hits);
112	  }
113	  return hits;
114	}
