 3	public struct HostRegistry: Equatable, Sendable {
 4	    public let hosts: [DockHostConfiguration]
 5	
 6	    public init(hosts: [DockHostConfiguration]) throws {
 7	        guard !hosts.isEmpty else {
 8	            DockLog.hostConfiguration.error("host registry creation failed reason=no_hosts")
 9	            throw DockHostConfigurationError.missingEndpoint
10	        }
11	        var seenHostIDs: Set<String> = []
12	        for host in hosts {
13	            guard seenHostIDs.insert(host.id).inserted else {
14	                DockLog.hostConfiguration.error("host registry creation failed reason=duplicate_endpoint endpoint=\(host.id, privacy: .public)")
15	                throw DockHostConfigurationError.duplicateHostID(host.id)
16	            }
17	        }
18	        self.hosts = hosts
19	        DockLog.hostConfiguration.notice("host registry created hosts=\(hosts.count, privacy: .public)")
20	    }
21	}
